ALTER TABLE upload_sessions ADD CONSTRAINT upload_sessions_tenant_fk FOREIGN KEY (tenant_id) REFERENCES tenants(id) ON DELETE CASCADE;
ALTER TABLE upload_sessions ADD CONSTRAINT upload_sessions_uploader_fk FOREIGN KEY (uploader_id) REFERENCES users(id) ON DELETE RESTRICT;
ALTER TABLE upload_chunks ADD CONSTRAINT upload_chunks_session_fk FOREIGN KEY (upload_id) REFERENCES upload_sessions(id) ON DELETE CASCADE;
